import { createWorkspace, teardownWorkspace } from "@tigrisdata/agent-kit";
import { S3Client, PutObjectCommand } from "@aws-sdk/client-s3";

async function main() {
  let workspace;
  try {
    // 1. Calls createWorkspace to provision a workspace named scoped-upload-ws with credentials: { role: "Editor" }.
    workspace = await createWorkspace({
      name: "scoped-upload-ws",
      credentials: { role: "Editor" },
    });

    // 2. Validates that both the bucket and scoped credentials are present in the response.
    if (!workspace.bucket) {
      throw new Error("Workspace bucket name is missing");
    }
    if (!workspace.credentials || !workspace.credentials.accessKeyId || !workspace.credentials.secretAccessKey) {
      throw new Error("Workspace scoped credentials (accessKeyId or secretAccessKey) are missing");
    }

    // 3. Uses the AWS SDK for JavaScript v3 configured with ONLY the scoped credentials.
    const s3 = new S3Client({
      region: "auto",
      endpoint: "https://t3.storage.dev",
      credentials: {
        accessKeyId: workspace.credentials.accessKeyId,
        secretAccessKey: workspace.credentials.secretAccessKey,
      },
    });

    // PutObject a file with key greeting.txt and body hello scoped into the workspace bucket.
    await s3.send(
      new PutObjectCommand({
        Bucket: workspace.bucket,
        Key: "greeting.txt",
        Body: "hello scoped",
      })
    );

    // 5. On success, prints a final line SCOPED_UPLOAD_OK <bucket-name>
    console.log(`SCOPED_UPLOAD_OK ${workspace.bucket}`);
  } catch (error) {
    console.error("Error during scoped upload process:", error);
    process.exit(1);
  } finally {
    // 4. Tears down the workspace at the end with teardownWorkspace.
    if (workspace) {
      try {
        await teardownWorkspace(workspace);
      } catch (teardownError) {
        console.error("Error during workspace teardown:", teardownError);
      }
    }
  }
}

main();

